  std::map<u32, Entry *> loaded_segments{};
  std::string label{""};
  Entry *root{nullptr};

  void print_tree(Entry *entry, u64 depth);
  void print_tree() {
    printf("Tree with label %s:", label.c_str());
    print_tree(root, 0);
